// The spec a bot actually plays. Returns nullptr for a class that is not a CoA
// class, and for a spec id we do not know.
static constexpr CoaSpecStrategy const* GetCoaSpecStrategy(uint8_t classId, uint16_t specId)
{
    for (CoaSpecStrategy const& e : CoaSpecStrategies)
        if (e.classId == classId && e.specId == specId)
            return &e;

    return nullptr;
}

// The default of a class: its first row. Used while a bot has no spec set yet.
static constexpr CoaSpecStrategy const* GetCoaDefaultSpecStrategy(uint8_t classId)
{
    for (CoaSpecStrategy const& e : CoaSpecStrategies)
        if (e.classId == classId)
            return &e;

    return nullptr;
}

